update public.task_solutions set solution = 'Teilaufgabe 1: Note = 30/50 · 5 + 1 = 0,6 · 5 + 1 = 4. Die Note ist 4 (auch als 4,0 richtig).
Teilaufgabe 2: Aus P/100 · 5 + 1 = 5,5 folgt P/100 · 5 = 4,5, also P = 90. Da auf eine Nachkommastelle gerundet wird, ergibt auch 89 Punkte die Note 5,5 (89/100 · 5 + 1 = 5,45 ≈ 5,5).
Teilaufgabe 3: Lösungsweg zu Teilaufgabe 2, z. B. die Gleichung P/100 · 5 + 1 = 5,5 nach P auflösen oder die Probe 90/100 · 5 + 1 = 5,5.
Teilaufgabe 4: Die Noten reichen von 1 bis 10, die Spanne ist also 9. Note = erreichte Punktzahl / Maximalpunktzahl · 9 + 1. Probe: 0 Punkte ergeben 1, die volle Punktzahl ergibt 10.' where task_id = 'c6990fb9-ae96-4a56-952e-da94736ac70f' and exists (select 1 from public.tasks d where d.id = 'c6990fb9-ae96-4a56-952e-da94736ac70f' and d.status = 'draft') and coalesce(btrim(solution), '') = '';
update public.task_solutions set hints = '[{"level":1,"text":"Setze die gegebenen Zahlen in die Formel ein: erreichte Punktzahl oben, Maximalpunktzahl unten."},{"level":2,"text":"Für Teilaufgabe 2 rechnest du rückwärts: Ziehe von 5,5 zuerst 1 ab und teile dann durch 5. Für die Niederlande überlege, wie viele Notenstufen zwischen 1 und 10 liegen."}]'::jsonb where task_id = 'c6990fb9-ae96-4a56-952e-da94736ac70f' and exists (select 1 from public.tasks d where d.id = 'c6990fb9-ae96-4a56-952e-da94736ac70f' and d.status = 'draft') and coalesce(hints, '[]'::jsonb) in ('[]'::jsonb, '{}'::jsonb);
update public.task_solutions set typical_errors = '[{"error":"In der Formel wird zuerst 5 + 1 gerechnet (Punkt-vor-Strich missachtet): 30/50 · 6 = 3,6.","socratic_question":"Welche Rechenart kommt in der Formel zuerst – das Mal oder das Plus?"},{"error":"Für die Niederlande wird der Faktor 10 statt 9 gewählt; dann ergibt die volle Punktzahl die Note 11.","socratic_question":"Welche Note ergibt deine Formel, wenn jemand alle Punkte erreicht hat?"}]'::jsonb where task_id = 'c6990fb9-ae96-4a56-952e-da94736ac70f' and exists (select 1 from public.tasks d where d.id = 'c6990fb9-ae96-4a56-952e-da94736ac70f' and d.status = 'draft') and coalesce(typical_errors, '[]'::jsonb) in ('[]'::jsonb, '{}'::jsonb);

