update public.task_solutions set solution = 'Teilaufgabe 1:
3x + 32 = 17x + 4 hat genau eine Lösung (unterschiedliche Faktoren vor x; x = 2).
x + 32 = x + 4 hat keine Lösung (gleicher Faktor vor x, aber 32 ≠ 4).
3 + 32x = 17 + 4x hat genau eine Lösung (unterschiedliche Faktoren vor x; x = 0,5).
Teilaufgabe 2: z. B. x + 2 = x + 2 oder 2(x + 1) = 2x + 2 – beide Seiten sind gleichwertige Terme, jede Zahl für x ergibt eine wahre Aussage.' where task_id = 'd3422f3d-85c0-46e5-b9a5-0e751e3c09c9' and exists (select 1 from public.tasks d where d.id = 'd3422f3d-85c0-46e5-b9a5-0e751e3c09c9' and d.status = 'draft') and coalesce(btrim(solution), '') = '';

