update public.task_solutions set typical_errors = '[{"error":"47² - 43² wird als (47 - 43)² gerechnet: 16.","socratic_question":"Ist 47² - 43² dasselbe wie (47 - 43)²? Probiere es mit kleinen Zahlen wie 3² - 2² aus."},{"error":"Nur (47 + 43) = 90 wird berechnet, der Faktor (47 - 43) = 4 fehlt.","socratic_question":"Aus wie vielen Faktoren besteht (a + b)(a - b)?"}]'::jsonb where task_id = '88ca2551-82bf-4ca3-b971-32cd4292a146' and exists (select 1 from public.tasks d where d.id = '88ca2551-82bf-4ca3-b971-32cd4292a146' and d.status = 'draft') and coalesce(typical_errors, '[]'::jsonb) in ('[]'::jsonb, '{}'::jsonb);

-- #23 Faktorisieren · vollständiges Quadrat · x² + 8x + 16
update public.tasks set est_duration_sec = 45 where id = 'b2bc0cfc-d927-4a29-aca4-4686606d9466' and status = 'draft' and est_duration_sec is null;
update public.task_solutions set solution = 'Gesucht sind a und b mit a² = x² und b² = 16, also a = x und b = 4.
Probe des Mischterms: 2 · x · 4 = 8x – passt.
x² + 8x + 16 = (x + 4)².' where task_id = 'b2bc0cfc-d927-4a29-aca4-4686606d9466' and exists (select 1 from public.tasks d where d.id = 'b2bc0cfc-d927-4a29-aca4-4686606d9466' and d.status = 'draft') and coalesce(btrim(solution), '') = '';
update public.task_solutions set hints = '[{"level":1,"text":"Von welcher Zahl ist 16 das Quadrat?"},{"level":2,"text":"Prüfe mit dem Mischterm: 2 · a · b muss 8x ergeben."}]'::jsonb where task_id = 'b2bc0cfc-d927-4a29-aca4-4686606d9466' and exists (select 1 from public.tasks d where d.id = 'b2bc0cfc-d927-4a29-aca4-4686606d9466' and d.status = 'draft') and coalesce(hints, '[]'::jsonb) in ('[]'::jsonb, '{}'::jsonb);
update public.task_solutions set typical_errors = '[{"error":"Der Mischterm wird direkt als b übernommen: (x + 8)². Ausmultipliziert ergibt das x² + 16x + 64.","socratic_question":"Multipliziere deine Klammer zur Probe aus – kommt wieder x² + 8x + 16 heraus?"}]'::jsonb where task_id = 'b2bc0cfc-d927-4a29-aca4-4686606d9466' and exists (select 1 from public.tasks d where d.id = 'b2bc0cfc-d927-4a29-aca4-4686606d9466' and d.status = 'draft') and coalesce(typical_errors, '[]'::jsonb) in ('[]'::jsonb, '{}'::jsonb);

-- #24 Faktorisieren · zweistufig · x⁴ - 16
update public.tasks set est_duration_sec = 90 where id = '9d904128-a0ae-449c-b7de-e1c57c8238c5' and status = 'draft' and est_duration_sec is null;
update public.task_solutions set solution = 'x⁴ - 16 = (x²)² - 4² = (x² + 4)(x² - 4).
Die zweite Klammer ist wieder eine Differenz von Quadraten: x² - 4 = (x + 2)(x - 2).
Also: x⁴ - 16 = (x² + 4)(x + 2)(x - 2).' where task_id = '9d904128-a0ae-449c-b7de-e1c57c8238c5' and exists (select 1 from public.tasks d where d.id = '9d904128-a0ae-449c-b7de-e1c57c8238c5' and d.status = 'draft') and coalesce(btrim(solution), '') = '';
update public.task_solutions set hints = '[{"level":1,"text":"Schreibe x⁴ als (x²)² und 16 als 4²."},{"level":2,"text":"Nach dem ersten Zerlegen: Lässt sich eine der Klammern noch einmal mit a² - b² zerlegen?"}]'::jsonb where task_id = '9d904128-a0ae-449c-b7de-e1c57c8238c5' and exists (select 1 from public.tasks d where d.id = '9d904128-a0ae-449c-b7de-e1c57c8238c5' and d.status = 'draft') and coalesce(hints, '[]'::jsonb) in ('[]'::jsonb, '{}'::jsonb);
update public.task_solutions set typical_errors = '[{"error":"Nach dem ersten Schritt wird aufgehört: (x² + 4)(x² - 4) – die Klammer x² - 4 lässt sich noch zerlegen.","socratic_question":"Ist x² - 4 selbst wieder eine Differenz von Quadraten?"}]'::jsonb where task_id = '9d904128-a0ae-449c-b7de-e1c57c8238c5' and exists (select 1 from public.tasks d where d.id = '9d904128-a0ae-449c-b7de-e1c57c8238c5' and d.status = 'draft') and coalesce(typical_errors, '[]'::jsonb) in ('[]'::jsonb, '{}'::jsonb);

-- #25 Fliesen
