update public.task_solutions set solution = 'Fläche des Badezimmers: 50 · 0,16 m² = 8 m².
Anzahl der neuen Fliesen: 8 m² : 0,2 m² = 40.
Es sind mindestens 40 Fliesen nötig. (Größere Fliesen – weniger Fliesen.)' where task_id = '6f552893-ec6d-4a73-b54d-17b0f2fd4dd6' and exists (select 1 from public.tasks d where d.id = '6f552893-ec6d-4a73-b54d-17b0f2fd4dd6' and d.status = 'draft') and coalesce(btrim(solution), '') = '';
